#!/bin/bash
# =====================================================================
# TMSK hero: replace the orbit rings with the "Legacy" stage
#
# HOW TO USE (from /workspaces/kebang-website)
#   1. Put this file in the project folder
#   2. Run:   bash fix-hero-legacy.sh
#   3. Look:  npm run dev -- --host
#   4. Happy? git add . && git commit -m "Hero legacy stage" && git push
#
# This file already contains your 4 images (shrunk to web size), so you do
# not need to upload them anywhere. They are saved to public/assets/legacy/
#
# WHAT YOU GET (top of the Home page, where the orbit rings were)
#   - Slowly turning golden sun rays with a pulsing glow behind everything
#   - Two war banners hanging from wooden poles that sway like in the wind:
#       the crossed-swords banner and the warrior-on-the-rock banner
#       (slow zoom, a golden shimmer that sweeps across, glowing halo)
#   - The two portrait cut-outs standing at the base like guardians,
#     in a warm old-photograph tone with a gold rim light, slowly breathing
#   - The TMSK flag card kept, still floating, set in front of the rock
#   - Red-gold embers rising like sparks from a war fire
#   - Everything marches in one after the other when the page loads
#   - On computers the layers shift slightly as the mouse moves (depth)
#   - All motion is switched off for people who prefer reduced motion
#
# SAFE: Home.jsx is backed up to /tmp/hero-legacy-backup-<time> first, and
# restored automatically if the site fails to build. Nothing is committed.
# =====================================================================

if [ ! -f src/pages/Home.jsx ] || [ ! -f src/pages/Home.css ]; then
  echo "Run this from /workspaces/kebang-website (src/pages/Home.jsx not found here)."
  exit 1
fi

BACKUP_DIR="/tmp/hero-legacy-backup-$(date +%Y%m%d-%H%M%S)"
mkdir -p "$BACKUP_DIR/src/pages"
cp src/pages/Home.jsx "$BACKUP_DIR/src/pages/Home.jsx"
echo "Backup saved in: $BACKUP_DIR"

restore_all() {
  echo "Restoring your files from the backup..."
  cp "$BACKUP_DIR/src/pages/Home.jsx" src/pages/Home.jsx
  rm -f src/components/HeroLegacy.jsx src/components/HeroLegacy.css
}

put() {
  mkdir -p "$(dirname "$1")"
  cat > "$1"
  echo "WROTE: $1"
}

# =====================================================================
# images
# =====================================================================
mkdir -p public/assets/legacy

