import { useEffect, useRef } from 'react'
import './HeroLegacy.css'

const BASE = '/assets/legacy'

// small deterministic set of sparks (no randomness, so it never flickers on re-render)
const EMBERS = Array.from({ length: 14 }, (_, i) => ({
  x: 8 + ((i * 29) % 84),
  s: 3 + (i % 4),
  d: 7 + (i % 5) * 1.5,
  dl: -((i * 1.7) % 9),
  dx: (i % 2 ? 1 : -1) * (12 + (i % 3) * 12),
}))

export default function HeroLegacy(){
  const rootRef = useRef(null)

  // gentle depth: layers drift a little as the mouse moves (computers only)
  useEffect(() => {
    const el = rootRef.current
    if (!el) return undefined
    const fine = window.matchMedia('(hover: hover) and (pointer: fine)').matches
    const calm = window.matchMedia('(prefers-reduced-motion: reduce)').matches
    if (!fine || calm) return undefined

    const hero = el.closest('.hero') || el
    let raf = 0
    const onMove = (e) => {
      cancelAnimationFrame(raf)
      raf = requestAnimationFrame(() => {
        const r = hero.getBoundingClientRect()
        const x = ((e.clientX - r.left) / r.width - 0.5) * 2
        const y = ((e.clientY - r.top) / r.height - 0.5) * 2
        el.style.setProperty('--px', x.toFixed(3))
        el.style.setProperty('--py', y.toFixed(3))
      })
    }
    const onLeave = () => {
      el.style.setProperty('--px', '0')
      el.style.setProperty('--py', '0')
    }
    hero.addEventListener('pointermove', onMove)
    hero.addEventListener('pointerleave', onLeave)
    return () => {
      cancelAnimationFrame(raf)
      hero.removeEventListener('pointermove', onMove)
      hero.removeEventListener('pointerleave', onLeave)
    }
  }, [])

  return (
    <div className="hero-flag lg-root" ref={rootRef}>
      <div className="lg-stage">
        <div className="lg-sun" aria-hidden="true"></div>
        <div className="lg-ground" aria-hidden="true"></div>

        {/* crossed-swords banner (behind) */}
        <div className="lg-layer lg-l-swords" aria-hidden="true">
          <div className="lg-banner lg-banner--swords">
            <div className="lg-cloth">
              <img src={`${BASE}/yoksaerkok.webp`} alt="" decoding="async" />
              <span className="lg-shine"></span>
            </div>
          </div>
        </div>

        {/* warrior banner (centre) */}
        <div className="lg-layer lg-l-warrior" aria-hidden="true">
          <div className="lg-banner lg-banner--warrior">
            <div className="lg-cloth">
              <img src={`${BASE}/abotani.webp`} alt="" decoding="async" />
              <span className="lg-shine"></span>
            </div>
          </div>
        </div>

        <div className="lg-embers" aria-hidden="true">
          {EMBERS.map((e, i) => (
            <i
              className="lg-ember"
              key={i}
              style={{
                '--x': `${e.x}%`,
                '--s': `${e.s}px`,
                '--d': `${e.d}s`,
                '--dl': `${e.dl}s`,
                '--dx': `${e.dx}px`,
              }}
            ></i>
          ))}
        </div>

        {/* the two portraits stand at the base */}
        <div className="lg-layer lg-l-elder-a" aria-hidden="true">
          <img className="lg-figure" src={`${BASE}/portrait-1.webp`} alt="" decoding="async" />
        </div>
        <div className="lg-layer lg-l-elder-b" aria-hidden="true">
          <img className="lg-figure" src={`${BASE}/portrait-2.webp`} alt="" decoding="async" />
        </div>

        {/* the TMSK flag card, kept */}
        <div className="lg-layer lg-l-flag">
          <div className="lg-flag">
            <img src="/assets/flag.jpg" alt="Flag of Takam Mising Sí:sang Kébang" />
            <span className="lg-badge">
              <span>EST.</span>
              <strong>2026</strong>
            </span>
          </div>
        </div>
      </div>
    </div>
  )
}
