/* ==================== HERO LEGACY STAGE ==================== */
.lg-root{
  --lg-ease:cubic-bezier(0.16,1,0.3,1);
  position:relative;
  display:flex;
  justify-content:center;
}
.lg-stage{
  position:relative;
  width:100%;
  max-width:520px;
  aspect-ratio:0.82;
}

/* every moving layer drifts a little with the mouse (the "translate" property),
   while its own animation uses "transform", so the two never fight */
.lg-layer{
  position:absolute;
  translate:calc(var(--px, 0) * var(--mx, 0px)) calc(var(--py, 0) * var(--my, 0px));
  transition:translate .6s var(--lg-ease);
}

/* ---- golden sun rays ---- */
.lg-sun{
  position:absolute;
  left:50%; top:30%;
  width:150%;
  aspect-ratio:1;
  translate:-50% -50%;
  pointer-events:none;
  animation:lgGlow 6s ease-in-out infinite;
}
.lg-sun::before{
  content:'';
  position:absolute;
  inset:0;
  border-radius:50%;
  background:repeating-conic-gradient(from 0deg, rgba(184,147,90,0.40) 0deg 3deg, transparent 3deg 12deg);
  -webkit-mask-image:radial-gradient(circle closest-side, transparent 22%, #000 32%, transparent 78%);
  mask-image:radial-gradient(circle closest-side, transparent 22%, #000 32%, transparent 78%);
  animation:lgSpin 140s linear infinite;
}
.lg-sun::after{
  content:'';
  position:absolute;
  inset:20%;
  border-radius:50%;
  background:radial-gradient(circle closest-side, rgba(200,16,46,0.20), rgba(184,147,90,0.10) 55%, transparent 100%);
}
.lg-ground{
  position:absolute;
  left:-12%; right:-12%; bottom:-3%;
  height:22%;
  pointer-events:none;
  background:radial-gradient(ellipse 60% 100% at 50% 100%, rgba(200,16,46,0.26), rgba(184,147,90,0.10) 50%, transparent 72%);
  animation:lgGlow 5s ease-in-out infinite;
}

/* ---- hanging war banners ---- */
.lg-l-swords{
  left:56%; top:3%;
  width:40%;
  z-index:1;
  --mx:-12px; --my:-8px;
  animation:lgDrop 1.5s var(--lg-ease) .5s both;
}
.lg-l-warrior{
  left:10%; top:4%;
  width:56%;
  z-index:2;
  --mx:-6px; --my:-4px;
  animation:lgDrop 1.6s var(--lg-ease) .15s both;
}

.lg-banner{
  position:relative;
  width:100%;
  transform-origin:50% 0;
  filter:drop-shadow(0 22px 24px rgba(20,17,14,0.30));
  animation:lgSway var(--sway, 8s) ease-in-out infinite;
}
.lg-banner--swords{--r:4deg;  --sway:7.5s; --notch:95%; --sd:3.2s;}
.lg-banner--warrior{--r:-1.2deg; --sway:10s; --notch:97%; --sd:1.4s;}

/* wooden pole the cloth hangs from */
.lg-banner::before{
  content:'';
  position:absolute;
  left:-7%; right:-7%; top:-8px;
  height:8px;
  z-index:2;
  border-radius:4px;
  background:linear-gradient(#ead09a, #8a6a35 60%, #5b4222);
  box-shadow:0 2px 6px rgba(20,17,14,0.35);
}
/* golden halo that breathes behind the warrior */
.lg-l-warrior::before{
  content:'';
  position:absolute;
  inset:-10% -22%;
  z-index:-1;
  pointer-events:none;
  background:radial-gradient(closest-side, rgba(255,196,90,0.55), transparent);
  animation:lgGlow 4.5s ease-in-out infinite;
}

.lg-cloth{
  position:relative;
  overflow:hidden;
  aspect-ratio:941 / 1672;
  clip-path:polygon(0 0, 100% 0, 100% 100%, 50% var(--notch, 95%), 0 100%);
  background:#7a0a1c;
}
.lg-cloth img{
  display:block;
  width:100%; height:100%;
  object-fit:cover;
  animation:lgKen 26s ease-in-out infinite alternate;
}
/* a shimmer of light sweeps across the cloth */
.lg-shine{
  position:absolute;
  inset:0;
  pointer-events:none;
  background:linear-gradient(105deg, transparent 38%, rgba(255,226,160,0.32) 46%, rgba(255,255,255,0.5) 50%, rgba(255,226,160,0.25) 54%, transparent 62%);
  transform:translateX(-130%);
  animation:lgShine 8s ease-in-out infinite;
  animation-delay:var(--sd, 2s);
}

/* ---- embers ---- */
.lg-embers{position:absolute; inset:0; z-index:3; pointer-events:none;}
.lg-ember{
  position:absolute;
  left:var(--x);
  bottom:6%;
  width:var(--s); height:var(--s);
  border-radius:50%;
  background:radial-gradient(circle, #ffd88a, #C8102E 72%);
  box-shadow:0 0 8px 2px rgba(229,72,91,0.55);
  opacity:0;
  animation:lgEmber var(--d) linear infinite;
  animation-delay:var(--dl);
}

/* ---- the two portraits ---- */
.lg-l-elder-a{
  left:-5%; bottom:0;
  width:27%;
  z-index:4;
  --mx:20px; --my:6px;
  animation:lgRise 1.5s var(--lg-ease) 1.2s both;
}
.lg-l-elder-b{
  right:-3%; bottom:0;
  width:30%;
  z-index:4;
  --mx:18px; --my:6px;
  animation:lgRise 1.5s var(--lg-ease) 1.4s both;
}
.lg-figure{
  display:block;
  width:100%;
  height:auto;
  transform-origin:50% 100%;
  filter:
    grayscale(0.55) sepia(0.35) contrast(1.06)
    drop-shadow(0 0 1.5px rgba(184,147,90,0.95))
    drop-shadow(0 18px 20px rgba(20,17,14,0.5));
  animation:lgBreathe 6s ease-in-out infinite;
}
.lg-l-elder-b .lg-figure{animation-delay:-3s;}

/* ---- flag card (kept) ---- */
.lg-l-flag{
  left:25%; bottom:1%;
  width:48%;
  z-index:5;
  --mx:14px; --my:8px;
  animation:lgRise 1.4s var(--lg-ease) 1s both;
}
.lg-flag{
  position:relative;
  padding:7px;
  background:var(--white);
  border:1px solid var(--line);
  box-shadow:0 30px 50px -20px rgba(20,17,14,0.5);
  transform:rotate(-2.5deg);
  animation:lgFloat 6.5s ease-in-out infinite;
}
.lg-flag img{width:100%; aspect-ratio:5 / 3; object-fit:cover;}
.lg-badge{
  position:absolute;
  right:-14px; top:-16px;
  width:clamp(54px, 13vw, 68px);
  aspect-ratio:1;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  border-radius:50%;
  background:var(--red);
  color:var(--white);
  line-height:1;
  box-shadow:0 0 0 5px var(--ivory);
}
.lg-badge span{font-size:8px; font-weight:500; letter-spacing:0.24em; text-transform:uppercase; opacity:0.85; margin-bottom:4px;}
.lg-badge strong{font-family:var(--f-display); font-size:21px; font-weight:600; letter-spacing:0;}

/* ---- motion ---- */
@keyframes lgSpin{to{transform:rotate(360deg);}}
@keyframes lgGlow{0%,100%{opacity:0.7;} 50%{opacity:1;}}
@keyframes lgSway{
  0%,100%{transform:rotate(calc(var(--r, 0deg) - 1.8deg)) skewX(-0.8deg);}
  50%{transform:rotate(calc(var(--r, 0deg) + 1.8deg)) skewX(0.8deg);}
}
@keyframes lgDrop{
  from{opacity:0; transform:translateY(-56px);}
  to{opacity:1; transform:none;}
}
@keyframes lgRise{
  from{opacity:0; transform:translateY(60px);}
  to{opacity:1; transform:none;}
}
@keyframes lgFloat{
  0%,100%{transform:rotate(-2.5deg) translateY(0);}
  50%{transform:rotate(-1deg) translateY(-10px);}
}
@keyframes lgBreathe{
  0%,100%{transform:scale(1);}
  50%{transform:scale(1.02);}
}
@keyframes lgKen{
  from{transform:scale(1) translateY(0);}
  to{transform:scale(1.09) translateY(-1.5%);}
}
@keyframes lgShine{
  0%,55%{transform:translateX(-130%);}
  85%,100%{transform:translateX(130%);}
}
@keyframes lgEmber{
  0%{opacity:0; transform:translate3d(0, 0, 0) scale(1);}
  12%{opacity:0.95;}
  100%{opacity:0; transform:translate3d(var(--dx), -420px, 0) scale(0.3);}
}

@media (max-width:980px){
  .lg-root{margin-bottom:8px;}
  .lg-stage{max-width:400px;}
}
@media (max-width:560px){
  .lg-stage{max-width:340px;}
  .lg-ember:nth-child(n+9){display:none;}
  .lg-badge{right:-10px; top:-12px;}
}
@media (prefers-reduced-motion: reduce){
  .lg-sun, .lg-sun::before, .lg-ground, .lg-banner, .lg-l-warrior::before,
  .lg-cloth img, .lg-shine, .lg-figure, .lg-flag{animation:none !important;}
  .lg-layer{translate:none; transition:none;}
  .lg-embers{display:none;}
}
__TMSK_FILE_END__

# =====================================================================
# Home.jsx : swap the orbit rings + old flag block for the new stage
# =====================================================================
python3 - << 'PYHOME'
import re, sys
p = 'src/pages/Home.jsx'
s = open(p, encoding='utf-8').read()

if 'HeroLegacy' in s:
    print('Home.jsx already uses HeroLegacy (nothing to change)')
    sys.exit(0)

m = re.search(r"import Reveal from '[^']*Reveal\.jsx'\n", s)
if not m:
    print("PROBLEM: could not find the Reveal import in Home.jsx"); sys.exit(1)
s = s[:m.end()] + "import HeroLegacy from '../components/HeroLegacy.jsx'\n" + s[m.end():]

s, n_orbit = re.subn(r'[ \t]*<div className="hero-ornament"[^>]*>.*?</div>[ \t]*\n(?:[ \t]*\n)?', '', s, count=1, flags=re.S)
s, n_flag = re.subn(r'<Reveal[^>]*className="hero-flag"[^>]*>.*?</Reveal>', '<HeroLegacy />', s, count=1, flags=re.S)

if n_flag != 1:
    print('PROBLEM: could not find the hero flag block in Home.jsx'); sys.exit(1)

open(p, 'w', encoding='utf-8').write(s)
print('UPDATED: Home.jsx (orbit rings removed: %s, flag block replaced)' % ('yes' if n_orbit else 'not found, already gone'))
PYHOME
if [ $? -ne 0 ]; then restore_all; echo "Paste Home.jsx here and I will fix the patch."; exit 1; fi

# =====================================================================
# make sure the site still builds
# =====================================================================
if [ -d node_modules ] && grep -q '"build"' package.json 2>/dev/null; then
  echo ""
  echo "Checking that the site builds..."
  BUILD_LOG=$(npm run build 2>&1)
  if [ $? -ne 0 ]; then
    echo "$BUILD_LOG" | tail -n 30
    echo ""
    echo "The build failed, so nothing was kept."
    restore_all
    echo "Copy the error above and paste it here and I will fix it."
    exit 1
  fi
  echo "Build OK."
fi

echo ""
echo "================ DONE ================"
echo "1) Look:  npm run dev -- --host   (open the Home page, wait a few seconds)"
echo "   Try moving the mouse over the hero, and check it on a phone-sized window."
echo "2) Keep:  git add . && git commit -m \"Hero legacy stage\" && git push"
echo "3) Undo:  cp $BACKUP_DIR/src/pages/Home.jsx src/pages/Home.jsx"
echo ""
echo "Easy edits later: src/components/HeroLegacy.css (sizes, speeds, colours)"
echo "                  src/components/HeroLegacy.jsx (which image goes where)"
